#pragma once

#include <stdbool.h>
#include <stdint.h>
#include "lvgl.h"

// Color emoji (Twemoji) for the message fonts; data generated by tools/gen_emoji.py
#define EMOJI_N_SIZES 3   // for font_pt_14, font_pt_20, font_pt_28

typedef struct {
    uint32_t cp;
    lv_image_dsc_t img[EMOJI_N_SIZES];
} emoji_t;

extern const uint8_t EMOJI_SIZES[EMOJI_N_SIZES];
extern const emoji_t EMOJI[];
extern const int EMOJI_COUNT;

// bigger images for the dashboard's weather icon
enum { EMOJI_BIG_SUN, EMOJI_BIG_MOON, EMOJI_BIG_CLOUD, EMOJI_N_BIG };
extern const lv_image_dsc_t EMOJI_BIG[EMOJI_N_BIG];

bool emoji_known(uint32_t cp);   // safe from any task
const lv_image_dsc_t *emoji_image(uint32_t cp, int size);   // size: index into EMOJI_SIZES; NULL if unknown
// Copies font_pt_14/20/28 with the emoji as fallback (call once, with the LVGL lock held).
// Returns the copy for one of them, or the font itself if it has no emoji.
const lv_font_t *emoji_font(const lv_font_t *font);
